// Process a single merged Odds+FD item OR multiple items.
// Handles: 
// - input item having Odds fields (home_team, away_team, bookmakers) AND a Football-Data "matches" array
// - or separate shapes where "oddsData" / "statsData.matches" are used upstream.

const items = $input.all();
const processed = [];

// ---------- Helpers ----------
const norm = (s) => (s || '')
  .toLowerCase()
  .normalize('NFKD')                // strip accents
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\b(afc|fc|sc|cf)\b/g, '') // drop common suffixes/prefixes
  .replace(/[^a-z0-9]+/g, ' ')       // non-alnum -> space
  .replace(/\s+/g, ' ')
  .trim();

const toKey = (h, a) => `${norm(h)}__${norm(a)}`;

// Build a Football-Data kickoff lookup from any item that has matches[]
const fdKickoff = {};
for (const it of items) {
  const mArr = Array.isArray(it.json?.matches)
    ? it.json.matches
    : (Array.isArray(it.json?.statsData?.matches) ? it.json.statsData.matches : []);
  for (const m of mArr) {
    const hName = m?.homeTeam?.name || m?.homeTeam?.shortName;
    const aName = m?.awayTeam?.name || m?.awayTeam?.shortName;
    const utc   = m?.utcDate;
    if (hName && aName && utc) {
      // store by multiple keys to improve matching (full + short names)
      fdKickoff[toKey(hName, aName)] = utc;

      // also add shortName combos if available
      if (m.homeTeam?.shortName && m.awayTeam?.shortName) {
        fdKickoff[toKey(m.homeTeam.shortName, m.awayTeam.shortName)] = utc;
      }
      // add combinations without "FC"/"AFC" etc. handled by norm()
    }
  }
}

// Collect odds matches to process.
// Case 1: each item itself is an odds object (has home_team/away_team & bookmakers)
let oddsObjects = [];
for (const it of items) {
  const j = it.json || {};
  if (j.home_team && j.away_team && Array.isArray(j.bookmakers)) {
    oddsObjects.push(j);
  }
}

// Case 2: upstream wrapped odds in an array j.oddsData
if (oddsObjects.length === 0) {
  for (const it of items) {
    const arr = Array.isArray(it.json?.oddsData) ? it.json.oddsData : [];
    for (const o of arr) {
      if (o.home_team && o.away_team && Array.isArray(o.bookmakers)) oddsObjects.push(o);
    }
  }
}

// If still nothing, nothing to return
if (oddsObjects.length === 0) {
  // Return nothing rather than throwing, so the workflow can proceed gracefully
  return [];
}

// For each odds object, compute best odds and attach matchTime (FD utcDate preferred)
for (const match of oddsObjects) {
  const homeTeam = match.home_team;
  const awayTeam = match.away_team;

  // Choose kickoff: prefer FD utcDate by normalized team names; else Odds commence_time
  const kickoff =
    fdKickoff[toKey(homeTeam, awayTeam)] ||
    // Try to match against common “FC”/“AFC” forms if inputs were different
    fdKickoff[toKey((match.teams?.home?.name || homeTeam), (match.teams?.away?.name || awayTeam))] ||
    match.commence_time ||
    null;

  // Scan all bookmakers to get the best (max) price for home/draw/away
  let bestHome = null, bestDraw = null, bestAway = null;
  let bookmakerCount = Array.isArray(match.bookmakers) ? match.bookmakers.length : 0;

  for (const bm of (match.bookmakers || [])) {
    const markets = bm.markets || [];
    const h2h = markets.find(m => ['h2h','match winner','full time result']
      .includes(String(m.key || m.name || '').toLowerCase()));
    if (!h2h || !Array.isArray(h2h.outcomes)) continue;

    // Outcomes may be named 'Home'/'Away'/'Draw' OR team names
    const pickPrice = (needle) => {
      const row = h2h.outcomes.find(o => norm(o.name) === norm(needle));
      return row ? Number(row.price) : null;
    };

    // Try explicit labels first
    const pHome = pickPrice('home') ?? pickPrice(homeTeam);
    const pDraw = pickPrice('draw');
    const pAway = pickPrice('away') ?? pickPrice(awayTeam);

    if (pHome != null) bestHome = Math.max(bestHome ?? -Infinity, pHome);
    if (pDraw != null) bestDraw = Math.max(bestDraw ?? -Infinity, pDraw);
    if (pAway != null) bestAway = Math.max(bestAway ?? -Infinity, pAway);
  }

  if (bestHome === -Infinity) bestHome = null;
  if (bestDraw === -Infinity) bestDraw = null;
  if (bestAway === -Infinity) bestAway = null;

  const matchIdDate = kickoff ? new Date(kickoff).toISOString().split('T')[0] : 'unknown_date';
  const processedMatch = {
    matchId: `${homeTeam.replace(/\s+/g, '_').toLowerCase()}_vs_${awayTeam.replace(/\s+/g, '_').toLowerCase()}_${matchIdDate}`,
    match: `${homeTeam} vs ${awayTeam}`,
    homeTeam,
    awayTeam,
    league: match.sport_title || match.league || 'EPL',
    matchTime: kickoff,

    homeOdds: bestHome,
    drawOdds: bestDraw,
    awayOdds: bestAway,

    bookmakerCount,
  };

  processed.push({ json: processedMatch });
}

return processed;

// ---------- Helpers ----------
const toNum = (v, d = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};

const fmtPercent = (n) => {
  const x = Number(n);
  if (!Number.isFinite(x)) return '0.0%';
  const sign = x > 0 ? '+' : x < 0 ? '' : '';
  return `${sign}${x.toFixed(1)}%`;
};

const riskLabel = (lvl) => {
  const n = Number(lvl);
  if (n <= 3) return 'Low';
  if (n <= 6) return 'Medium';
  if (n <= 8) return 'Elevated';
  return 'High';
};

const formatUKTime = (iso) => {
  if (!iso) return 'TBD';
  try {
    return new Date(iso).toLocaleString('en-GB', {
      timeZone: 'Europe/London',
      day: '2-digit', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit', hour12: false,
    });
  } catch { return 'TBD'; }
};

const extractJson = (text) => {
  if (typeof text !== 'string') return null;
  // handle ```json ... ``` or ``` ... ```
  const fenced = text.match(/```json\s*([\s\S]*?)```/i) || text.match(/```\s*([\s\S]*?)```/);
  const body = fenced ? fenced[1] : text;
  const jsonOnly = body.match(/\{[\s\S]*\}/);
  if (!jsonOnly) return null;
  try { return JSON.parse(jsonOnly[0]); } catch { return null; }
};

const first = (...vals) => {
  for (const v of vals) {
    if (v !== undefined && v !== null) return v;
  }
  return null;
};

// ---------- Main ----------
const items = $input.all();
const out = [];

for (const item of items) {
  try {
    // 1) Pull agent output (string or object)
    const aiResponse =
      item.json?.message?.content ??
      item.json?.response ??
      item.json?.output ??
      '';

    const analysis = (aiResponse && typeof aiResponse === 'object')
      ? aiResponse
      : (extractJson(aiResponse) || {});

    // 2) Pull original match data if present (works when you Merge the original with Agent output)
    const matchData = {
      ...(item.json || {}),
      ...(item.json?.original || {}),
      ...(item.json?.input || {}),
    };

    // 3) Build base tip using analysis first where applicable, with safe fallbacks to matchData
    const tip = {
      matchId: analysis.matchId || matchData.matchId || 'unknown',
      match: (analysis.match && String(analysis.match)) ||
             (matchData.homeTeam && matchData.awayTeam
               ? `${matchData.homeTeam} vs ${matchData.awayTeam}`
               : 'unknown match'),
      league: matchData.league,

      // prefer original kickoff; fallback to agent echo if provided
      matchTime: first(matchData.matchTime, analysis.matchTime),

      prediction: analysis.prediction || 'no prediction',
      confidence: toNum(analysis.confidence, 0),
      expectedScore: analysis.expectedScore || 'N/A',

      recommendedBet: analysis.recommendedBet || 'No bet',
      stake: toNum(analysis.stake, 0),
      riskLevel: toNum(analysis.riskLevel, 5),

      expectedValue: toNum(analysis.expectedValue, 0),

      // Odds: prefer original fields, else agent echo
      odds: {
        home: first(matchData.homeOdds, matchData.odds?.home, analysis.homeOdds),
        draw: first(matchData.drawOdds, matchData.odds?.draw, analysis.drawOdds),
        away: first(matchData.awayOdds, matchData.odds?.away, analysis.awayOdds),
      },

      keyFactors: Array.isArray(analysis.keyFactors) ? analysis.keyFactors : [],
      alternativeBets: Array.isArray(analysis.alternativeBets) ? analysis.alternativeBets : [],
      warnings: Array.isArray(analysis.warnings) ? analysis.warnings : [],

      timestamp: new Date().toISOString(),

      // Bookmakers: prefer original count, else agent echo, else 0
      bookmakers: first(
        (typeof matchData.bookmakerCount === 'number') ? matchData.bookmakerCount : null,
        (typeof analysis.bookmakerCount === 'number') ? analysis.bookmakerCount : null,
        Array.isArray(matchData.bookmakers) ? matchData.bookmakers.length : null,
        0
      ),

      // Value bet flag (your existing rule)
      isValueBet: false,

      // Preformatted display (no confidence bar)
      display: {}
    };

    // 4) Compute value flag
    tip.isValueBet = tip.confidence >= 65 && tip.expectedValue > 5;

    // 5) Display bundle for Telegram
    tip.display = {
      predictionUpper: tip.prediction ? String(tip.prediction).toUpperCase() : 'N/A',
      matchTimeFormatted: formatUKTime(tip.matchTime),
      oddsLine: `Home: ${tip.odds.home ?? 'N/A'} | Draw: ${tip.odds.draw ?? 'N/A'} | Away: ${tip.odds.away ?? 'N/A'}`,
      expectedValuePct: fmtPercent(tip.expectedValue),
      riskLabel: riskLabel(tip.riskLevel),
    };

    out.push({ json: tip });

  } catch (err) {
    out.push({
      json: {
        matchId: 'error',
        match: 'Processing Error',
        prediction: 'no prediction',
        confidence: 0,
        expectedScore: 'N/A',
        recommendedBet: 'No bet',
        stake: 0,
        riskLevel: 5,
        expectedValue: 0,
        odds: { home: null, draw: null, away: null },
        keyFactors: [],
        alternativeBets: [],
        warnings: [String(err?.message || err)],
        timestamp: new Date().toISOString(),
        bookmakers: 0,
        isValueBet: false,
        display: {
          predictionUpper: 'N/A',
          matchTimeFormatted: 'TBD',
          oddsLine: 'Home: N/A | Draw: N/A | Away: N/A',
          expectedValuePct: fmtPercent(0),
          riskLabel: riskLabel(5),
        },
      },
    });
  }
}

return out;

