// Input: the raw Odds API response on item.json (adjust 'data' if yours differs)
const items = $input.all();
const out = [];

for (const item of items) {
  const data = item.json; // <-- adjust if nested
  const bookmakers = Array.isArray(data.bookmakers) ? data.bookmakers : [];

  // Find a 1X2 market (common ids: 'h2h', 'Match Winner', 'Full Time Result')
  const getMarket = (bm) => (bm.markets || []).find(m =>
    ['h2h','match winner','full time result'].includes(String(m.key || m.name || '').toLowerCase())
  );
  // Collect outcomes across all bookmakers (first non-empty wins)
  let home = null, draw = null, away = null;

  for (const bm of bookmakers) {
    const market = getMarket(bm);
    if (!market || !Array.isArray(market.outcomes)) continue;

    // outcomes might be like [{name:'Home', price:2.1}, {name:'Draw', price:3.4}, {name:'Away', price:3.6}]
    const byName = (n) => market.outcomes.find(o => String(o.name || '').toLowerCase() === n)?.price ?? null;

    home ??= byName('home');
    draw ??= byName('draw');
    away ??= byName('away');

    // Some APIs use team names instead of 'Home/Away'
    if (home == null || away == null) {
      const homeTeam = String(data.homeTeam || data.teams?.home?.name || '').toLowerCase();
      const awayTeam = String(data.awayTeam || data.teams?.away?.name || '').toLowerCase();
      const byTeam = (t) => market.outcomes.find(o => String(o.name || '').toLowerCase() === t)?.price ?? null;
      if (home == null && homeTeam) home = byTeam(homeTeam);
      if (away == null && awayTeam) away = byTeam(awayTeam);
    }

    if (home != null && draw != null && away != null) break;
  }

  out.push({
    json: {
      ...item.json,
      homeOdds: home ?? null,
      drawOdds: draw ?? null,
      awayOdds: away ?? null,
      bookmakerCount: bookmakers.length,
    },
  });
}

return out;

